// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { facetValuesShown } from "../../../main/frontend/graph-explorer/graph-facets.ts";

const values = Array.from({ length: 40000 }, (_, index) => ({ id: `v${index}`, label: `Node ${index}`, count: 40000 - index }));

test("a filter with tens of thousands of values shows the first few, and the selected ones wherever they are", () => {
  const shown = facetValuesShown(values, new Set(["v39999"]), 12, "");
  assert.equal(shown.values.length, 13);
  assert.deepEqual(shown.values.slice(0, 2).map((value) => value.id), ["v0", "v1"]);
  assert.equal(shown.values.at(-1).id, "v39999");
  assert.equal(shown.more, 39987);
});

test("a search looks through every value, not only the shown ones", () => {
  const shown = facetValuesShown(values, new Set(), 12, "node 3999");
  assert.deepEqual(shown.values.map((value) => value.id).slice(0, 2), ["v3999", "v39990"]);
  assert.equal(shown.values.length, 11);
  assert.equal(shown.more, 0);
});
